var catMenu=document.getElementById("mob-cat-menu");function showMenu(){catMenu.classList.contains("collapse")||catMenu.classList.toggle("collapse");document.getElementById("mob-nav").style.width="100%"}function closeMenu(){let t=document.querySelector("body");t.style.height="90vh",t.style.overflow="hidden";document.getElementById("mob-nav").style.width="0"}function menu(){catMenu.classList.toggle("collapse")}window.onscroll=function(){myFunction()};var header=document.getElementById("desktop-menu"),mobHeader=document.getElementById("search"),desCatMenu=document.getElementById("desktop-cat-menu"),mobCartButton=document.getElementById("mob-cart-button"),menuButton=document.getElementById("menu-button"),sticky=header.offsetTop;function myFunction(){window.pageYOffset>sticky?(header.classList.add("sticky"),mobHeader.classList.add("sticky"),desCatMenu.classList.add("cat-sticky"),mobCartButton.classList.add("mob-sticky"),menuButton.classList.add("mob-sticky")):(header.classList.remove("sticky"),mobHeader.classList.remove("sticky"),desCatMenu.classList.remove("cat-sticky"),mobCartButton.classList.remove("mob-sticky"),menuButton.classList.remove("mob-sticky"))}